cd /tmp/ross-wt && python3 - <<'PY'
import subprocess, re, os
branches=['rachel','monica','phoebe','joey','chandler','ross']
commits=[]
for b in branches:
    out=subprocess.check_output(['git','log','--format=%H', 'origin/friend/'+b], text=True)
    for sha in out.split():
        msg=subprocess.check_output(['git','log','-1','--format=%B', sha], text=True)
        if re.search(r'^Friend-Message: 1\s*$', msg, re.M):
            m=re.search(r'^Episode: (.*)$', msg, re.M)
            ep=m.group(1).strip() if m else '?'
